using File=CodexKit.Native.NativeFile;
using Directory=CodexKit.Native.NativeDirectory;
using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Text.RegularExpressions;using CodexKit.Native;
namespace CodexKit {
internal static class NativeDesktopWorker {
    internal static NativeServices Services(NativePaths p,Dictionary<string,object> options,int port,Action<string> log){var o=NativeDesktopWorkflow.Options(options,port);var services=NativeCli.Services(p,o);services.Log=log;services.Downloads=new NativeGitHubDownloads(new GitHubNetworkOptions{githubMirrorEnabled=(bool)options["githubMirrorEnabled"],customGithubMirror=Core.Value(options,"customGithubMirror","")},port,o.ProxyHost,log);return services;}
    internal static int Run(string operation,string drive,int port,bool guard,Dictionary<string,object> supplied,Action<string> log){
        NativeRuntime.Configure();var p=NativePaths.Current();p.EntryPrefix="--native ";p.Workspace=drive+@":\Codex";var settings=Core.NormalizeOptions(supplied);var services=Services(p,settings,port,log);var options=NativeDesktopWorkflow.Options(settings,port);var components=new NativeDesktopComponents(p,services,settings,port,log);
        try{
            if(operation=="ws-start-info"){log("@@WS_APP@@"+Core.Json.Serialize(NativeDesktopWorkflow.WebSocketInfo(p,services,options)));return 0;}
            if(operation=="initialize-preflight"){log("@@INIT_PREFLIGHT@@"+Core.Json.Serialize(NativeDesktopWorkflow.Preflight(p,services,options,settings)));return 0;}
            if(operation=="status"){log("@@STATUS@@"+Core.Json.Serialize(NativeDesktopState.Status(p,services,components)));return 0;}
            if(operation=="initialize"){
                using(var mutex=new Mutex(false,"Local\\CodexInitNative-"+Core.Sid)){bool owned=false;try{try{owned=mutex.WaitOne(0);}catch(AbandonedMutexException){owned=true;}if(!owned)throw new IOException("另一个初始化操作正在运行，请等待完成。");return new NativeDesktopWorkflow(p,services,settings,components,log).Run(options,guard);}finally{if(owned)mutex.ReleaseMutex();}}
            }
            if(operation=="init-rollback"){var result=new NativeInitializer(p,services).Run("rollback",options,null);foreach(var item in result.steps)log(item.message);return result.state=="complete"?0:1;}
            if(operation=="rollback-selected"){var id=Core.Value(settings,"rollbackId","");var entry=NativeDesktopState.Entries(p,services).SingleOrDefault(x=>(string)x["id"]==id);if(entry==null||!(bool)entry["available"])throw new IOException("回滚列表已变化或该版本不完整，请刷新后重新选择。");if((string)entry["kind"]=="cli"){components.CachedCli((string)entry["path"]);return 0;}var result=new NativeInitializer(p,services).Run("rollback",options,(string)entry["path"]);foreach(var item in result.steps)log(item.message);return result.state=="complete"?0:1;}
            if(operation=="rollback-delete-all"){var status=NativeDesktopState.Status(p,services,components);if(Core.Value(settings,"rollbackId","")!=Core.Value(status,"rollbackDeleteId","")||Core.Value(status,"rollbackDeleteId","")=="")throw new IOException("备份列表已变化，请刷新后重新确认删除。");foreach(var entry in NativeDesktopState.Entries(p,services).Where(x=>!(bool)x["protected"])){var path=(string)entry["path"];var root=(string)entry["kind"]=="init"?p.BackupRoot:Path.Combine(p.Home,"packages","standalone","releases");if(!NativeData.Inside(path,root))throw new IOException("备份目录不在允许清理的范围。");CheckDeleteTree(path);NativeDirectory.Delete(path,true);log("已删除回滚备份："+path);}return 0;}
            if(operation=="desktop-update"){components.DesktopUpdate();return 0;}
            if(operation=="official-cli-update"||operation=="guard-update"){components.OfficialCli(false);return 0;}
            if(operation=="guard-install"){components.Protection();return 0;}
            if(operation=="guard-native"){components.SelectCli("desktop-native");components.VerifyCli("desktop-native");return 0;}
            if(operation=="guard-current"){components.OfficialCli(true);components.SelectCli("official-standalone");components.VerifyCli("official-standalone");return 0;}
            if(operation=="browser-repair"){components.Browser();return 0;}
            if(operation=="proxy"){var reconcile=new NativeDesktopReconcile(p,services,options);try{var result=reconcile.Run(true);foreach(var step in result.steps)log(step.name+"："+step.message);return result.state=="complete"?0:1;}finally{foreach(var effect in reconcile.Changes)log("【配置生效】"+effect.name+"\n"+effect.Detail);}}
            if(operation=="cua-check"||operation=="cua-repair"){var result=new NativeCua(p,services).Run(operation=="cua-repair",Path.Combine(p.BackupRoot,"CUA_"+DateTime.Now.ToString("yyyyMMdd-HHmmss")));log("CUA 组件："+(result.Passed?result.Changed?"已修复并校验":"完整，无需修复":"不完整，请选择修复"));log("运行时目录："+result.Target);return result.Passed?0:1;}
            throw new ArgumentException("未支持的原生桌面操作。");
        }catch(Exception ex){DesktopProfile.ReportFailure(ex,log);log("操作未完成："+ex.GetBaseException().Message);if(operation=="initialize")log("@@INIT_RESULT@@"+Core.Json.Serialize(new{state="failed",summary="初始化未完成："+ex.GetBaseException().Message,steps=new object[0]}));return 1;}finally{if(operation!="initialize")foreach(var effect in components.Changes)log("【配置生效】"+effect.name+"\n"+effect.Detail);}
    }
    static void CheckDeleteTree(string path){NativeData.NoLinks(path);foreach(var dir in NativeDirectory.GetDirectories(path,"*"))CheckDeleteTree(dir);}
    internal static int Maintain(){var p=NativePaths.Current();var settings=Core.NormalizeOptions(null);Directory.CreateDirectory(Core.Logs);var logFile=Path.Combine(Core.Logs,"native-guard-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".log");using(var writer=new StreamWriter(logFile,false,new UTF8Encoding(false))){writer.AutoFlush=true;Action<string> log=writer.WriteLine;try{var services=Services(p,settings,0,log);new NativeDesktopComponents(p,services,settings,0,log).AutoMaintain();return 0;}catch(Exception ex){log("登录维护未完成："+ex.Message);return 1;}}}
}
internal static class NativeDesktopState {
    internal static Dictionary<string,object> Status(NativePaths p,NativeServices s,NativeDesktopComponents c){OfficialDesktop app=null;string health="尚未检测";try{app=s.Desktop.Discover();health="已找到官方桌面包";}catch(Exception ex){health=ex.Message;}
        var mode="Unknown";try{mode=c.DetectCli()=="desktop-native"?"DesktopNative":c.DetectCli()=="official-standalone"?"OfficialStandalone":"Unknown";}catch(Exception ex){health+="；CLI 检查："+ex.Message;}
        var config=File.Exists(p.Config)?NativeData.Read(p.Config):"";var model=ManagedToml.SavedValue(config,"model");var effort=ManagedToml.SavedValue(config,"model_reasoning_effort");var entries=Entries(p,s);var removable=entries.Where(x=>!(bool)x["protected"]).ToArray();var latest=entries.FirstOrDefault(x=>(string)x["kind"]=="init");bool healthy=app!=null&&c.DesktopSafe&&new[]{"codex.exe","codex-code-mode-host.exe","codex-command-runner.exe","codex-windows-sandbox-setup.exe"}.All(x=>File.Exists(Path.Combine(app.Install,"app","resources",x)));var user=s.Registry.Get("CODEX_CLI_PATH");var cli=user.Exists?Convert.ToString(user.Value):Convert.ToString(s.Registry.GetMachine("CODEX_CLI_PATH").Value);
        return new Dictionary<string,object>{{"backendVersion",Core.Version},{"desktopVersion",app==null?"未检测":app.Version},{"desktopHealth",health},{"desktopHealthy",healthy},{"desktopFound",app!=null},{"desktopInstallLocation",app==null?"":app.Install},{"configModel",model},{"configEffort",effort},{"configWorkspace",ManagedToml.SavedValue(config,"desktop","projectlessWorkspaceRoot")},{"configProxy",SavedProxy(p.Home)},{"checkedAt",DateTime.Now.ToString("o")},{"config",new{model=model,effort=effort,path=p.Config,exists=File.Exists(p.Config)}},{"protectionInstalled",c.ProtectionInstalled},{"protectionRoot",c.GuardRoot},{"root",Core.Root},{"processRunning",s.Processes.List(p,app).Count>0},{"runtimeMode",mode},{"runtimeModeDetail",mode=="DesktopNative"?"已保存选择：桌面原生 CLI；当前运行实例未核验。":mode=="OfficialStandalone"?"已保存选择：官方独立 CLI；当前运行实例未核验。":"无法确认 CLI 类型，请到 CLI 管理检查。"},{"currentCliPath",cli??""},{"backupPath",latest==null?p.BackupRoot:latest["path"]},{"backupRoot",p.BackupRoot},{"latestBackupPath",latest==null?"":latest["path"]},{"statePath",c.StateFile},{"rollbackEntries",entries},{"rollbackError",""},{"rollbackDeleteId",removable.Length==0?"":NativeCua.HashBytes(Encoding.UTF8.GetBytes(String.Join(",",removable.Select(x=>(string)x["id"]).OrderBy(x=>x,StringComparer.OrdinalIgnoreCase))))},{"rollbackDeleteCount",removable.Length},{"rollbackProtectedCount",entries.Count-removable.Length}};
    }
    static string SavedProxy(string home){try{var p=ProxyPortSettings.LoadAddress(home);return p.Configured?new UriBuilder("http",p.Host,p.Port).Uri.AbsoluteUri.TrimEnd('/'):"未配置 HTTP 代理";}catch(Exception ex){return "读取未完成："+ex.Message;}}
    static string Toml(string text,string key){var top=Regex.Split(text,@"(?m)^\s*\[")[0];var m=Regex.Match(top,@"(?m)^\s*"+key+"\\s*=\\s*\"([^\"]*)\"");return m.Success?m.Groups[1].Value:"未设置";}
    internal static List<Dictionary<string,object>> Entries(NativePaths p,NativeServices s){var result=new List<Dictionary<string,object>>();var standalone=Path.Combine(p.Home,"packages","standalone");var references=new List<string>();bool unknown=false;var current=Path.Combine(standalone,"current");if(Directory.Exists(current))try{references.Add(NativeJunction.Resolve(current));}catch{unknown=true;}foreach(var name in new[]{"CODEX_CLI_PATH","CODEX_CODE_MODE_HOST_PATH"})foreach(var value in new[]{s.Registry.Get(name),s.Registry.GetMachine(name)})if(value.Exists&&!String.IsNullOrWhiteSpace(Convert.ToString(value.Value)))references.Add(Convert.ToString(value.Value));var stateFile=Path.Combine(p.Documents,"Codex启动保护管理器","State","guard-state.json");if(File.Exists(stateFile))try{var state=NativeData.Json.Deserialize<Dictionary<string,object>>(NativeData.Read(stateFile));foreach(var key in new[]{"ActiveCliPath","OriginalCliPath"})if(Core.Value(state,key,"")!="")references.Add(Core.Value(state,key,""));}catch{unknown=true;}
        var runningReferences=new List<string>();try{OfficialDesktop app=null;try{app=s.Desktop.Discover();}catch(FileNotFoundException){}foreach(var process in s.Processes.List(p,app)){if(String.IsNullOrWhiteSpace(process.Path))unknown=true;else runningReferences.Add(process.Path);}}catch{unknown=true;}
        foreach(var kind in new[]{"init","cli"}){var root=kind=="init"?p.BackupRoot:Path.Combine(standalone,"releases");if(!Directory.Exists(root))continue;foreach(var directory in Directory.GetDirectories(root,"*")){var dir=new DirectoryInfo(NativePath.Io(directory));if((dir.Attributes&FileAttributes.ReparsePoint)!=0||kind=="init"&&!Regex.IsMatch(dir.Name,@"^Codex_Full_Reset_[A-Za-z0-9_.-]+$")||kind=="cli"&&dir.Name.StartsWith("."))continue;var marker=Path.Combine(directory,kind=="init"?"session.meta":"codex-package.json");bool available=File.Exists(marker)&&(kind!="init"||Directory.Exists(Path.Combine(directory,"Backups")));var data=Encoding.UTF8.GetBytes(kind+"|"+directory.ToUpperInvariant()+"|"+dir.CreationTimeUtc.Ticks);if(File.Exists(marker))data=data.Concat(File.ReadAllBytes(marker)).ToArray();var version="版本未记录";if(kind=="cli"){try{version=Core.Value(NativeData.Json.Deserialize<Dictionary<string,object>>(NativeData.Read(marker)),"version",version);}catch{available=false;}available&=new[]{"bin/codex.exe","bin/codex-code-mode-host.exe","codex-path/rg.exe","codex-resources/codex-command-runner.exe","codex-resources/codex-windows-sandbox-setup.exe"}.All(x=>File.Exists(Path.Combine(directory,x.Replace('/',Path.DirectorySeparatorChar))));}else{if(available)try{var session=NativeSession.Load(directory,p);available=session.files.All(x=>!x.Existed||File.Exists(Path.Combine(directory,"Backups",x.Backup)));}catch{available=false;}var vf=Path.Combine(directory,"desktop-version.txt");if(File.Exists(vf))version="备份工具 v"+NativeData.Read(vf).Trim();else if(File.Exists(Path.Combine(directory,"session.json")))version="原生初始化本地版";}
            bool inUse=kind=="cli"&&runningReferences.Any(x=>NativeData.Inside(x,directory));bool protect=kind=="cli"&&(inUse||unknown||references.Any(x=>String.Equals(Path.GetFullPath(x),directory,StringComparison.OrdinalIgnoreCase)||NativeData.Inside(x,directory)));result.Add(new Dictionary<string,object>{{"id",NativeCua.HashBytes(data)},{"kind",kind},{"version",version},{"time",dir.CreationTime.ToString("yyyy-MM-dd HH:mm:ss")},{"path",directory},{"available",available},{"protected",protect},{"detail",protect?inUse?"运行中的 CLI 正在使用，清理时保留。":unknown?"当前使用状态未能完全确认，清理时保留。":"已保存配置引用的 CLI，清理时保留。":available?kind=="init"?"配置、代理和全局规则备份。":"本地官方独立 CLI 缓存。":"备份或组件不完整，无法回滚。"}});
        }}return result.OrderByDescending(x=>(string)x["time"]).ToList();
    }
}
}
